export const LANG_SUMMARY_LINES = {"corrected": {"en": ["Thank you, I have updated that. Is there anything else I have misunderstood or missed?", "Thank you, that is updated. Is there anything else I should correct?"], "fr": ["Merci, c'est mis à jour. Y a-t-il autre chose que j'aurais mal compris ou oublié ?", "Merci, c'est corrigé. Y a-t-il autre chose que je devrais rectifier ?"], "es": ["Gracias, ya lo he actualizado. ¿Hay algo más que haya entendido mal o se me haya pasado?", "Gracias, queda actualizado. ¿Hay algo más que deba corregir?"], "pt": ["Obrigado, já atualizei isso. Há mais alguma coisa que eu tenha entendido mal ou deixado passar?", "Obrigado, está atualizado. Há mais alguma coisa que eu deva corrigir?"], "de": ["Danke, das ist aktualisiert. Habe ich sonst noch etwas falsch verstanden oder übersehen?", "Danke, das ist angepasst. Soll ich sonst noch etwas korrigieren?"], "it": ["Grazie, ho aggiornato. C'è altro che ho capito male o che mi è sfuggito?", "Grazie, è aggiornato. C'è altro che dovrei correggere?"], "nl": ["Dank je, dat is bijgewerkt. Heb ik nog iets verkeerd begrepen of gemist?", "Dank je, dat is aangepast. Moet ik nog iets corrigeren?"]}, "prompt": {"en": ["Thanks, that is everything I need. When you are ready, press Confirm summary. It saves a private draft only you can see, and nothing goes to a reviewer until you submit it."], "fr": ["Merci, j'ai tout ce qu'il me faut. Quand vous êtes prêt, appuyez sur « Confirm summary ». Cela enregistre un brouillon privé que vous seul voyez, et rien n'est transmis à un relecteur tant que vous ne l'envoyez pas."], "es": ["Gracias, tengo todo lo que necesito. Cuando estés listo, pulsa «Confirm summary». Guarda un borrador privado que solo tú ves, y nada llega a un revisor hasta que lo envíes."], "pt": ["Obrigado, tenho tudo de que preciso. Quando estiver pronto, aperte «Confirm summary». Isso salva um rascunho privado que só você vê, e nada vai para um revisor até você enviar."], "de": ["Danke, das ist alles, was ich brauche. Wenn Sie bereit sind, klicken Sie auf „Confirm summary“. Das speichert einen privaten Entwurf, den nur Sie sehen, und nichts geht an einen Prüfer, bevor Sie es einreichen."], "it": ["Grazie, ho tutto quello che mi serve. Quando sei pronto, premi «Confirm summary». Salva una bozza privata che vedi solo tu, e nulla arriva a un revisore finché non la invii."], "nl": ["Dank je, dat is alles wat ik nodig heb. Als je klaar bent, druk je op «Confirm summary». Dat bewaart een privéconcept dat alleen jij ziet, en niets gaat naar een beoordelaar totdat je het indient."]}, "saved": {"en": ["Thank you. Your summary is saved as a private draft that only you can see. Press Submit for review when you are ready; until then it goes nowhere."], "fr": ["Merci. Votre résumé est enregistré comme brouillon privé que vous seul voyez. Appuyez sur « Submit for review » quand vous êtes prêt ; d'ici là, il ne va nulle part."], "es": ["Gracias. Tu resumen queda guardado como borrador privado que solo tú ves. Pulsa «Submit for review» cuando estés listo; hasta entonces no va a ninguna parte."], "pt": ["Obrigado. Seu resumo foi salvo como rascunho privado que só você vê. Aperte «Submit for review» quando estiver pronto; até lá, ele não vai a lugar nenhum."], "de": ["Danke. Ihre Zusammenfassung ist als privater Entwurf gespeichert, den nur Sie sehen. Klicken Sie auf „Submit for review“, wenn Sie bereit sind; bis dahin geht sie nirgendwohin."], "it": ["Grazie. Il tuo riepilogo è salvato come bozza privata che vedi solo tu. Premi «Submit for review» quando sei pronto; fino ad allora non va da nessuna parte."], "nl": ["Dank je. Je samenvatting is bewaard als privéconcept dat alleen jij ziet. Druk op «Submit for review» als je klaar bent; tot die tijd gaat het nergens heen."]}, "unsaved": {"en": ["Thank you. Your summary is confirmed, but it could not be saved to the library, so nothing was filed. You can try again from your notes."], "fr": ["Merci. Votre résumé est confirmé, mais il n'a pas pu être enregistré dans la bibliothèque, donc rien n'a été classé. Vous pouvez réessayer depuis vos notes."], "es": ["Gracias. Tu resumen está confirmado, pero no se pudo guardar en la biblioteca, así que no se archivó nada. Puedes intentarlo de nuevo desde tus notas."], "pt": ["Obrigado. Seu resumo foi confirmado, mas não foi possível salvá-lo na biblioteca, então nada foi arquivado. Você pode tentar de novo a partir das suas notas."], "de": ["Danke. Ihre Zusammenfassung ist bestätigt, konnte aber nicht in der Bibliothek gespeichert werden, daher wurde nichts abgelegt. Sie können es über Ihre Notizen erneut versuchen."], "it": ["Grazie. Il tuo riepilogo è confermato, ma non è stato possibile salvarlo nella libreria, quindi non è stato archiviato nulla. Puoi riprovare dalle tue note."], "nl": ["Dank je. Je samenvatting is bevestigd, maar kon niet in de bibliotheek worden bewaard, dus er is niets opgeslagen. Je kunt het opnieuw proberen vanuit je notities."]}};
